INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich in einer objektrelationalen Datenbank direkt Objekte speichern?', 2, '[{"text": "Ja", "correct": true, "because": "Unterstützt komplexe Datentypen"}, {"text": "Nein", "correct": false, "because": "Nicht auf Tabellen beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Vorteil, wenn ich Objekte mit relationalen Tabellen kombiniere?', 3, '[{"text": "SQL-Kompatibilität mit Objektlogik", "correct": true, "because": "Erweitert Abfragemöglichkeiten"}, {"text": "Kleinere Datenbankgröße", "correct": false, "because": "Kein primärer Vorteil"}, {"text": "Schnellere Schreibvorgänge", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features unterstützt so ein System typischerweise?', 5, '[{"text": "Benutzerdefinierte Typen", "correct": true, "because": "Erlaubt komplexe Objekte"}, {"text": "Vererbung", "correct": true, "because": "Unterstützt Hierarchien"}, {"text": "Prozedurale Programmierung", "correct": false, "because": "Weniger relevant"}, {"text": "Feste Schemata", "correct": false, "because": "Flexibilität ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objektrelationale Datenbanken nutzen SQL. b) Sie ersetzen NoSQL-Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist kontextabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht immer wahr"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines solchen Systems?', 4, '[{"text": "Abfrageoptimierung", "correct": false, "because": "Wichtig für Performance"}, {"text": "Komplexe Typen", "correct": false, "because": "Kernfeature"}, {"text": "Echtzeitverarbeitung", "correct": true, "because": "Nicht primär unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SQL allein für komplexe Objekte ausreicht?', 2, '[{"text": "Nein", "correct": true, "because": "Erweiterungen wie UDTs nötig"}, {"text": "Ja", "correct": false, "because": "SQL ist begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Konzept ist für die Arbeit mit Hierarchien entscheidend?', 3, '[{"text": "Vererbung", "correct": true, "because": "Ermöglicht Typenhierarchien"}, {"text": "Primärschlüssel", "correct": false, "because": "Nur für Identifikation"}, {"text": "Normalisierung", "correct": false, "because": "Relationale Optimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Datenverwaltung wichtig?', 5, '[{"text": "Benutzerdefinierte Funktionen", "correct": true, "because": "Erweitern Logik"}, {"text": "Tabellenbeziehungen", "correct": true, "because": "Relationale Basis"}, {"text": "Hohe Kompression", "correct": false, "because": "Sekundär"}, {"text": "Statische Typen", "correct": false, "because": "Flexibilität bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solche Datenbanken unterstützen Kapselung. b) Sie sind immer schneller als relationale. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Anwendungen ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht universell"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Arbeit mit komplexen Objekten?', 4, '[{"text": "Erweiterte Typen", "correct": false, "because": "Kern der Funktionalität"}, {"text": "SQL-Erweiterungen", "correct": false, "because": "Notwendig für Abfragen"}, {"text": "Prozedurale Skripte", "correct": true, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind objektrelationale Systeme immer schemafrei?', 2, '[{"text": "Nein", "correct": true, "because": "Kombinieren feste und flexible Schemata"}, {"text": "Ja", "correct": false, "because": "Nicht wie NoSQL"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für flexible Datenmodelle?', 4, '[{"text": "Benutzerdefinierte Typen", "correct": true, "because": "Ermöglichen komplexe Strukturen"}, {"text": "Feste Indizes", "correct": false, "because": "Weniger flexibel"}, {"text": "Hohe Schreibrate", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Systeme immer teurer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten hängen von Implementierung ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teurer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Abfrage von Objekten entscheidend?', 3, '[{"text": "Erweiterte Abfragesprache", "correct": true, "because": "Unterstützt komplexe Typen"}, {"text": "Einfache Joins", "correct": false, "because": "Nur relational primär"}, {"text": "Statische Schemata", "correct": false, "because": "Einschränken Flexibilität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Objektrelationale Datenbanken unterstützen Methoden. b) Sie eliminieren Normalisierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Normalisierung bleibt relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein solches System?', 5, '[{"text": "Komplexe Datenmodelle", "correct": true, "because": "Unterstützt Objekte"}, {"text": "SQL-Kompatibilität", "correct": true, "because": "Nutzt Standardabfragen"}, {"text": "Echtzeit-Analysen", "correct": false, "because": "Nicht primär"}, {"text": "Minimale Latenz", "correct": false, "because": "Hängt von Optimierung ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Modellierung unwichtig?', 3, '[{"text": "Objektbeziehungen", "correct": false, "because": "Kern der Struktur"}, {"text": "Abfrageoptimierung", "correct": false, "because": "Wichtig für Performance"}, {"text": "Physische Speichergröße", "correct": true, "because": "Abstrahiert durch DBMS"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob solche Systeme immer proprietär sind?', 2, '[{"text": "Nein", "correct": true, "because": "Es gibt Open-Source-Optionen"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig proprietär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Unterstützen solche Datenbanken Polymorphismus?', 3, '[{"text": "Ja", "correct": true, "because": "Durch Typenhierarchien möglich"}, {"text": "Nein", "correct": false, "because": "Teil der Objektlogik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt am besten für den Einsatz?', 4, '[{"text": "Multimedia-Daten mit Beziehungen", "correct": true, "because": "Nutzt komplexe Typen"}, {"text": "Einfache Tabellenabfragen", "correct": false, "because": "Rein relational besser"}, {"text": "Echtzeit-Transaktionen", "correct": false, "because": "Nicht primär optimiert"}]');
